//! Result contract shared by every engine call that can change matrix data.
//!
//! `DataModificationResult` is serialized through `serde-wasm-bindgen` and its
//! TypeScript declaration is generated by `tsify` into the wasm-bindgen
//! `.d.ts`, so Rust and the frontend share a single typed definition.

use serde::Serialize;
use tsify::{Ts, Tsify};
use wasm_bindgen::UnwrapThrowExt;
use wasm_bindgen::convert::IntoWasmAbi;
use wasm_bindgen::describe::WasmDescribe;

use crate::{MsaEngine, StructuredEngineError};

/// Outcome of a successful data-modifying engine call.
///
/// Compatibility rules for this wire type:
/// - It stays a struct; success values are never a bare `bool` or tuple.
/// - Changes are additive only. New fields must be `Option<T>` with
///   `#[serde(skip_serializing_if = "Option::is_none")]`; existing fields are
///   never renamed, removed, or redefined without a deliberate breaking change.
/// - Consumers must ignore fields they do not know.
/// - Every field must serialize infallibly (see the `IntoWasmAbi` impl below).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Tsify)]
#[serde(rename_all = "camelCase")]
pub struct DataModificationResult {
    /// Whether the call changed engine data, i.e. the `revision` advanced.
    pub changed: bool,
    /// Engine revision after the call.
    pub revision: usize,
}

// The wasm-bindgen ABI cannot report conversion failures, which is why tsify
// deprecated `#[tsify(into_wasm_abi)]` in favour of `Ts<T>`. Delegating to
// `Ts<T>` here is sound only because serializing this struct cannot fail:
// it holds plain booleans and numbers (`usize` is `u32` on wasm32). Keep any
// new field infallible to serialize (numbers, strings, `Option`, `Vec`) so the
// `unwrap_throw` below stays unreachable. This lets `#[wasm_bindgen]` methods
// return the struct directly while native Rust callers and tests use it as-is.
impl WasmDescribe for DataModificationResult {
    fn describe() {
        <Ts<Self> as WasmDescribe>::describe()
    }
}

impl IntoWasmAbi for DataModificationResult {
    type Abi = <Ts<Self> as IntoWasmAbi>::Abi;

    fn into_abi(self) -> Self::Abi {
        self.into_ts().unwrap_throw().into_abi()
    }
}

impl MsaEngine {
    /// Runs `operation` and reports whether it advanced the engine revision.
    ///
    /// No-op paths inside `operation` leave `revision` untouched, so they are
    /// reported as `changed: false` without each path building a result.
    pub(crate) fn track_modification(
        &mut self,
        operation: impl FnOnce(&mut Self) -> Result<(), StructuredEngineError>,
    ) -> Result<DataModificationResult, StructuredEngineError> {
        let before = self.revision;
        operation(self)?;
        Ok(DataModificationResult {
            changed: self.revision != before,
            revision: self.revision,
        })
    }
}
